function podozdat(condition, callback, options) {
    const opts = options || {};
    const intervalMs = opts.interval || 100;
    const maxAttempts = opts.maxAttempts || 100;
    const warnMessage = opts.warnMessage || 'podozdat: timeout';
    let attempts = 0;

    const tick = setInterval(() => {
        attempts += 1;
        if (attempts > maxAttempts) {
            clearInterval(tick);
            console.warn(warnMessage);
            return;
        }
        try {
            if (condition()) {
                clearInterval(tick);
                callback();
            }
        } catch (_) {}
    }, intervalMs);
}

function klonSoSlezhkoy(target, onChange) {
    const clone = JSON.parse(JSON.stringify(target));
    return new Proxy(clone, {
        set(obj, key, value, receiver) {
            const prev = obj[key];
            const result = Reflect.set(obj, key, value, receiver);
            if (prev !== value) onChange(key, value, prev);
            return result;
        }
    });
}

window.loaderModule = window.loaderModule || {};
loaderModule.utils = loaderModule.utils || {
    isNumber(value) {
        return !isNaN(value) && typeof value === 'number';
    },
    createStyles(css, className) {
        if (document.querySelector(`style.${className}`)) return;
        const style = document.createElement('style');
        style.innerHTML = css;
        if (className) style.className = className;
        document.head.appendChild(style);
    }
};

loaderModule.notification = {
    $style: '.loader-module-notification{display:flex;align-items:center;position:fixed;right:30px;font-weight:700;font-size:17px;color:#2e2e2e;background-color:#f8f8f8;border-radius:7px;box-shadow:0 2px 20px rgb(0 0 0 / .3);padding:14px;margin-bottom:10px;opacity:0;transition:opacity .5s,bottom .5s;z-index:100000}.loader-module-notification.show{opacity:1}.loader-module-notification .loader-module-icon{width:34px;height:34px;margin-right:14px;vertical-align:middle;flex-shrink:0}.loader-module-notification .loader-module-progress-bar{height:3px;border-radius:5px;position:absolute;bottom:0;left:0;width:100%}.loader-module-notification .loader-module-progress{border-radius:5px;height:100%;background-color:currentColor;transition:width linear}.loader-module-notification.loader-module-slide-in{animation:.7s forwards notificationSlideIn}@keyframes notificationSlideIn{0%{right:-250px}100%{right:30px}}',
    $count: 0,
    icons: {
        success: {
            icon: 'data:image/png;base64,',
            color: '#4ca476'
        },
        error: {
            icon: 'data:image/png;base64,',
            color: '#e92f3f'
        },
        info: {
            icon: 'data:image/png;base64,',
            color: '#1f9de0'
        }
    },
    show(message, type = 'info', duration = 3000) {
        if (!message || !loaderModule.utils.isNumber(duration)) return;
        const iconType = loaderModule.notification.icons[type] ? type : 'info';
        const iconData = loaderModule.notification.icons[iconType];

        const node = document.createElement('div');
        node.className = `loader-module-notification loader-module-${iconType}`;
        node.style.borderLeft = `5px solid ${iconData.color}`;
        node.style.bottom = `${30 + 70 * loaderModule.notification.$count}px`;

        const icon = document.createElement('img');
        icon.className = 'loader-module-icon';
        icon.src = iconData.icon;
        icon.alt = '';
        icon.draggable = false;
        node.appendChild(icon);

        const text = document.createElement('span');
        text.style.flexGrow = '1';
        text.textContent = message;
        node.appendChild(text);

        const progressBar = document.createElement('div');
        progressBar.className = 'loader-module-progress-bar';
        const progress = document.createElement('div');
        progress.className = 'loader-module-progress';
        progress.style.backgroundColor = iconData.color;
        progress.style.width = '100%';
        progressBar.appendChild(progress);
        node.appendChild(progressBar);

        loaderModule.notification.$count++;
        const delay = 600 * (loaderModule.notification.$count - 1);

        setTimeout(() => {
            document.body.appendChild(node);
            setTimeout(() => {
                node.classList.add('show', 'loader-module-slide-in');
                setTimeout(() => {
                    progress.style.transitionDuration = `${duration}ms`;
                    progress.style.width = '0%';
                }, 50);
            }, 100);
            setTimeout(() => {
                node.classList.remove('show');
                setTimeout(() => {
                    if (node.isConnected) node.remove();
                    loaderModule.notification.$count--;
                    document.querySelectorAll('.loader-module-notification').forEach((el, index) => {
                        el.style.bottom = `${30 + 70 * index}px`;
                    });
                }, 200);
            }, duration);
        }, delay);
    },
    init() {
        loaderModule.utils.createStyles(loaderModule.notification.$style, 'LoaderModuleNotifications');
    }
};

function showEpilepsiaNotification(title, text, type = 'info', duration = 3000) {
    const message = text ? `${title}: ${text}` : String(title || '');
    if (loaderModule.notification?.show) {
        loaderModule.notification.show(message, type, duration);
        return;
    }
    if (typeof window.createNotification === 'function') {
        window.createNotification(title, text);
    }
}

loaderModule.notification.init();
window.createNotification = (title, text) => showEpilepsiaNotification(title, text, 'info', 3000);

function primenitCaptureTableCss() {
    const tpl = window.__captureTableCssTemplate;
    if (!tpl) return;
    let el = document.getElementById('capture-table-css');
    if (!el) {
        el = document.createElement('style');
        el.id = 'capture-table-css';
        document.head.appendChild(el);
    }
    el.textContent = tpl;
}

