        'init'() {
            if (window.__speedometrGotov) return;

            podozdat(
                () => {
                    if (typeof window.interface !== 'function') return false;
                    const hud = window.interface('Hud');
                    return !!(hud && hud.speedometer);
                },
                () => {
                    this.setStyles();
                    const el = this.mountSpeedometer(this.buildHtml());
                    if (el) this.createSpeedometer(el.classList.contains('speedometr') ? el : el.querySelector('.speedometr') || el);
                    if (window.interface('Hud')?.speedometer) window.interface('Hud').speedometer.show = 0x0;
                    window.__speedometrGotov = true;
                    window.naborSpeedometra = this;
                    if (typeof jsLoader !== 'undefined' && jsLoader.log && jsLoader.log.makeLog) {
                        jsLoader.log.makeLog('BOSS_HUD', '[speedometer init] Inited!');
                    }
                },
                { warnMessage: 'Speedometer initialization timeout: window.interface not available' }
            );
        }
