(function initConfigfunChatHelper() {
    if (window.__configfunChatHelper) return;
    window.__configfunChatHelper = true;
    window.__configfunCommands = window.__configfunCommands || [];

    window.podklyuchitKomanduChata = function (command, handler) {
        if (window.__configfunCommands.some((c) => c.command === command)) return;
        window.__configfunCommands.push({ command, handler });

        window.__mostChata.configfun = window.__mostChata.configfun || {};
        window.__mostChata.configfun.tryHandle = function (text) {
            const msg = String(text == null ? '' : text).trim();
            if (!msg) return false;
            const msgLower = msg.toLowerCase();
            for (const c of window.__configfunCommands) {
                if (msg === c.command || msgLower === c.command.toLowerCase()) {
                    c.handler(msg);
                    return true;
                }
            }
            return false;
        };

        if (typeof jsLoader !== 'undefined' && jsLoader.chat?.registerCommand) {
            jsLoader.chat.registerCommand(command, (...a) => handler(a.map((x) => (x == null ? '' : String(x))).join('').trim() || command));
        }

        const ensureChatHook = () => {
            if (typeof window.perehvatChata !== 'function') return false;
            window.perehvatChata();
            return !!(window.__mostChata?.wrap && window.sendChatInput === window.__mostChata.wrap);
        };

        if (ensureChatHook()) return;

        if (window.__configfunChatPodozdat) return;
        window.__configfunChatPodozdat = true;

        podozdat(
            () => typeof window.sendChatInput === 'function',
            () => {
                if (!ensureChatHook() && !window.__configfunChatHooked) {
                    const orig = window.sendChatInput;
                    window.sendChatInput = function (...a) {
                        const msg = a.map((x) => (x == null ? '' : String(x))).join('').trim();
                        const msgLower = msg.toLowerCase();
                        for (const c of window.__configfunCommands) {
                            if (msg === c.command || msgLower === c.command.toLowerCase()) {
                                c.handler(msg);
                                return;
                            }
                        }
                        return orig.apply(this, a);
                    };
                    window.__configfunChatHooked = true;
                }
            },
            { warnMessage: 'configfun: timeout waiting for sendChatInput', maxAttempts: 200, interval: 100 }
        );
    };
})();

