(function initInterfaceModule() {
    if (window.__interfaceModuleLoaded) return;
    window.__interfaceModuleLoaded = true;

    if (!document.querySelector('link[href*="interface/style.css"]')) {
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'ScriptLoader-hud/interface/style.css';
        document.head.appendChild(link);
    }

    let interfaceStyle = null;

    function hexToRgb(hex) {
        hex = hex.replace(/^#/, '');
        if (hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
        if (hex.length !== 6) return null;
        return {
            r: parseInt(hex.substring(0, 2), 16),
            g: parseInt(hex.substring(2, 4), 16),
            b: parseInt(hex.substring(4, 6), 16),
        };
    }

    function getLuminance(r, g, b) {
        const [r0, g0, b0] = [r, g, b].map((c) => {
            c = c / 255;
            return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
        });
        return 0.2126 * r0 + 0.7152 * g0 + 0.0722 * b0;
    }

    function applyInterfaceColor(inputColor) {
        let color = inputColor.trim();
        if (!color) return;
        if (color[0] !== '#') color = '#' + color;

        if (!/^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(color)) {
            notifyConfigfun('Интерфейс', 'Неверный # цвет', 'error');
            return;
        }

        if (color.length === 4) {
            color = '#' + color[1] + color[1] + color[2] + color[2] + color[3] + color[3];
        }

        const rgb = hexToRgb(color);
        if (!rgb) return;

        const luminance = getLuminance(rgb.r, rgb.g, rgb.b);
        const textColor = luminance > 0.5 ? '#000000' : '#FFFFFF';
        const borderColor = luminance > 0.5 ? '#00000033' : '#FFFFFF33';
        const alpha = '80';

        const css = `
            #app .modal-container,
            #app .modal-container-wrapper { background: ${color} !important; }
            #app .player-interaction__inner { background: ${color} !important; border: .09vh solid ${borderColor} !important; }
            #app .player-interaction-layer { background: ${color}${alpha} !important; }
            #app .player-interaction__container { background: ${color}${alpha} !important; }
            #app .player-interaction-favorite { background: ${color}${alpha} !important; }
            #app .player-interaction-favorite:hover { background: ${color}${alpha} !important; }
            #app .container { background: ${color}${alpha} !important; }
            #app .input-field { background: ${color}${alpha} !important; color: ${textColor} !important; border: 1px solid ${borderColor} !important; }
            #app .fuel__container { background: ${color}${alpha} !important; }
            #app .controls-button { background: ${color}${alpha} !important; }
            #app .radmir-chat-input__input { background: ${color}${alpha} !important; border: 1px solid ${borderColor} !important; }
            #app .inventory-action__modal { background: ${color}${alpha} !important; }
            .inventory-container__info__container { background: ${color}${alpha} !important; }
            #app .inventory-extra__container,
            #app .inventory-main { background: ${color}${alpha} !important; }
            #app .trade-items__container { background: ${color}${alpha} !important; }
        `;

        if (interfaceStyle) interfaceStyle.remove();
        const style = document.createElement('style');
        style.innerHTML = css;
        document.head.appendChild(style);
        interfaceStyle = style;

        notifyConfigfun('Интерфейс', `Цвет: ${color}`, 'success');
    }

    function openInterfaceMenu() {
        window.addDialogInQueue(
            `[0,1,"Цвет интерфейса","Введите Цвет (#FF0000)","Применить","Закрыть",0,0]`,
            '',
            0
        );

        const orig = window.sendClientEvent;
        window.sendClientEvent = function (...args) {
            if (args.includes('OnDialogResponse')) {
                applyInterfaceColor((args[5] || '').trim());
                window.sendClientEvent = orig;
            }
            return orig.apply(this, args);
        };
    }

    window.podklyuchitKomanduChata('/interface', openInterfaceMenu);
})();

(function initDialogModule() {
    if (window.__dialogModuleLoaded) return;
    window.__dialogModuleLoaded = true;

    const maincss = {
        modern: "",
        legacy: "",
    };
    let currentDialogStyle = 'modern';
    let dialogStyleEl = null;

    if (!maincss.modern) return;

    function applyDialogStyle(type) {
        const css = maincss[type];
        if (!css) return;
        currentDialogStyle = type;
        if (dialogStyleEl) dialogStyleEl.remove();
        dialogStyleEl = document.createElement('style');
        dialogStyleEl.id = 'epilepsia-dialog-style';
        dialogStyleEl.textContent = css;
        document.head.appendChild(dialogStyleEl);
    }

    function setDialog(type, name) {
        applyDialogStyle(type);
        notifyConfigfun('Диалоги', `Выбран: ${name}`, 'success');
    }

    function resolveDialogChoice(resp, args) {
        const idx = Number(resp.listitem);
        const blob = [resp.listitem, resp.input, args[5], args[6], args[7]]
            .map((v) => String(v == null ? '' : v))
            .join(' ')
            .toLowerCase();

        if (idx === 0 || blob.includes('нов')) {
            return { type: 'modern', name: 'Новые' };
        }
        if (idx === 1 || blob.includes('стар')) {
            return { type: 'legacy', name: 'Старые' };
        }
        return null;
    }

    function openDialogMenu() {
        const list = 'Новые<n>Старые';

        window.addDialogInQueue(
            `[0,2,"Смена диалогов ScriptLoader","Выберите стиль диалогов:","Выбрать","Закрыть",0,0]`,
            list,
            0
        );

        const orig = window.sendClientEvent;
        window.sendClientEvent = function (...args) {
            if (!args.includes('OnDialogResponse')) {
                return orig.apply(this, args);
            }

            const resp = razobratOtvetDialoga(args);
            if (resp && resp.btn !== 0) {
                const pick = resolveDialogChoice(resp, args);
                if (pick) setDialog(pick.type, pick.name);
            }

            window.sendClientEvent = orig;
            return orig.apply(this, args);
        };
    }

    applyDialogStyle(currentDialogStyle);
    window.podklyuchitKomanduChata('/dialog', openDialogMenu);
})();

